'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useId, useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { UsersIcon } from '@/registry/ndeko/lib/icons';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { Wash } from '@/registry/ndeko/ui/wash';

import { MEMBERS, SECTION } from './data';
import { MemberProfile } from './member-profile';
import { PeoplePicker, tabIdOf } from './people-picker';

const PICK_MS = 3800;

const ENTER: Transition = { duration: 0.4, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const PROFILE_VARIANTS: Variants = {
  enter: { opacity: 0, y: 6, filter: 'blur(4px)' },
  shown: { opacity: 1, y: 0, filter: 'blur(0px)', transition: ENTER },
  gone: { opacity: 0, filter: 'blur(4px)', transition: EXIT },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  shown: { opacity: 1, transition: ENTER },
  gone: { opacity: 0, transition: EXIT },
};

function variantsOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return PROFILE_VARIANTS;
}

function indexAfter(index: number) {
  const next = index + 1;
  return next % MEMBERS.length;
}

/** The next person after each one, so a round ends on the first person and the loop shows no seam. */
const ROTATION = MEMBERS.map((_, index) => indexAfter(index));

function spokenMemberOf(index: number) {
  const member = MEMBERS[index];
  return `Showing ${member.name}, ${member.role} in ${member.location}`;
}

export default function TeamSections03() {
  const [activeIndex, setActiveIndex] = useState(0);
  const [message, setMessage] = useState('');
  const { pressed, press } = usePress<string>();
  const idBase = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const activeMember = MEMBERS[activeIndex];
  const panelId = `${idBase}-panel`;
  const activeTabId = tabIdOf(idBase, activeMember.id);
  const variants = variantsOf(shouldReduceMotion);

  const steps = ROTATION.flatMap((index) => [
    { after: PICK_MS, run: () => press(MEMBERS[index].id) },
    { after: PRESS_LEAD_MS, run: () => setActiveIndex(index) },
  ]);
  const { ref } = useAutoplay<HTMLElement>(steps, { loopAfter: 0 });

  function pick(memberId: string) {
    const index = MEMBERS.findIndex((member) => member.id === memberId);
    setActiveIndex(index);
    setMessage(spokenMemberOf(index));
  }

  return (
    <section ref={ref} className='@container'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex max-w-2xl flex-col gap-3'>
          <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
            <UsersIcon className='size-4' />
            {SECTION.label}
          </p>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.lead}
          </p>
        </header>
        <div className='flex flex-col gap-4'>
          <PeoplePicker
            members={MEMBERS}
            activeId={activeMember.id}
            pressedId={pressed}
            tabIdBase={idBase}
            panelId={panelId}
            onPick={pick}
          />
          <div
            id={panelId}
            role='tabpanel'
            aria-labelledby={activeTabId}
            className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] relative isolate rounded-2xl p-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @2xl:p-8'
          >
            <Wash />
            <div className='grid *:col-start-1 *:row-start-1'>
              {MEMBERS.map((member) => (
                <div
                  key={member.id}
                  aria-hidden='true'
                  inert
                  className='invisible'
                >
                  <MemberProfile member={member} />
                </div>
              ))}
              <AnimatePresence initial={false}>
                <motion.div
                  key={activeMember.id}
                  variants={variants}
                  initial='enter'
                  animate='shown'
                  exit='gone'
                >
                  <MemberProfile member={activeMember} />
                </motion.div>
              </AnimatePresence>
            </div>
          </div>
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import type { Member } from './data';

export function tabIdOf(base: string, memberId: string) {
  return `${base}-tab-${memberId}`;
}

const SPOTLIGHT =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.07] pointer-events-none absolute top-0 left-0 h-(--active-tab-height) w-(--active-tab-width) translate-x-(--active-tab-left) translate-y-(--active-tab-top) rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.06),0_4px_12px_-4px_rgb(0_0_0/0.08)]';

function travelOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return 'transition-none';
  }
  return 'transition-[translate,width,height] duration-300 ease-(--ease-out-strong)';
}

function isMemberId(value: unknown, members: readonly Member[]) {
  return members.some((member) => member.id === value);
}

type PeoplePickerProps = {
  members: readonly Member[];
  activeId: string;
  pressedId: string | null;
  tabIdBase: string;
  panelId: string;
  onPick: (memberId: string) => void;
};

export function PeoplePicker({
  members,
  activeId,
  pressedId,
  tabIdBase,
  panelId,
  onPick,
}: PeoplePickerProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  function pickTab(value: unknown) {
    if (isMemberId(value, members)) {
      onPick(String(value));
    }
  }

  return (
    <TabsPrimitive.Root value={activeId} onValueChange={pickTab}>
      <TabsPrimitive.List
        activateOnFocus
        aria-label='Pick a person'
        className='relative isolate flex flex-wrap gap-1'
      >
        {members.map((member) => (
          <TabsPrimitive.Tab
            key={member.id}
            value={member.id}
            id={tabIdOf(tabIdBase, member.id)}
            aria-controls={panelId}
            aria-label={`${member.name}, ${member.role}`}
            className={cn(
              'group/person hover:bg-foreground/[0.03] focus-visible:ring-ring/25 flex min-w-0 cursor-pointer items-center gap-3 rounded-xl p-2 text-start transition-[background-color,scale] duration-150 ease-(--ease-out-strong) outline-none focus-visible:ring-[3px] data-active:hover:bg-transparent @3xl:pe-4',
              pressedQuietOf(pressedId === member.id)
            )}
          >
            <Avatar seed={member.name} className='size-10' />
            <span className='hidden min-w-0 flex-col @3xl:flex'>
              <span className='text-muted-foreground group-data-active/person:text-foreground truncate text-[13px] font-medium transition-colors duration-150'>
                {member.name}
              </span>
              <span className='text-muted-foreground hidden truncate text-xs @5xl:block'>
                {member.role}
              </span>
            </span>
          </TabsPrimitive.Tab>
        ))}
        <TabsPrimitive.Indicator
          className={cn('-z-10', SPOTLIGHT, travelOf(shouldReduceMotion))}
        />
      </TabsPrimitive.List>
    </TabsPrimitive.Root>
  );
}

import {
  GithubIcon,
  LinkedinBrandIcon,
  MailIcon,
  MapPinIcon,
  TwitterXIcon,
